contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: amount is the wei sent to c.play()
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has enough balance to send `amount` if needed
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;

        // We cannot reference the TICKET_AMOUNT constant directly, so use the known literal 10
        // General rule as a single assert:
        // - If amount != 10 then the call must revert.
        // - If amount == 10 then balAfter >= balBefore - 10, rewritten safely as balAfter + 10 >= balBefore.
        assert((amount != 10 ? reverted : true) && (amount == 10 ? (balAfter + 10 >= balBefore) : true));
    }

    // allow receiving refunds from c
    receive() external payable {}
}

